    ['home', 'testimonial_1', 'company', 'text', 'H2 Games', 'H2 Games', null, 13],
    ['home', 'testimonial_2', 'photo', 'image', 'Laila Alsaadi, Founder', 'ليلى السعدي، المؤسسة', 'https://f.nooncdn.com/s/app/pr-comms/sell-with-us/01-testimonial-04.jpg', 20],
    ['home', 'testimonial_2', 'quote', 'richtext', '“I’ve always been passionate about e-commerce, which is why I chose to sell on Nawy and join Mahali. Getting paid for my first sale was an empowering moment that made me feel truly supported.”', 'لطالما كنت شغوفة بالتجارة الإلكترونية، ولهذا قررت البيع على ناوي والانضمام إلى برنامج مهلي. حصولي على أول دفعة بعد أول عملية بيع كان لحظة مليئة بالتمكين، وجعلتني أشعر بالدعم الحقيقي.', null, 21],
    ['home', 'testimonial_2', 'name', 'text', 'Laila Alsaadi, Founder', 'ليلى السعدي، المؤسسة', null, 22],
    ['home', 'testimonial_2', 'company', 'text', 'Heyraat General Trading', 'Heyraat General Trading', null, 23],
    ['home', 'testimonial_3', 'photo', 'image', 'Zouban Shalin, Brand Director', 'زوبان شالين، مدير العلامة التجارية', 'https://f.nooncdn.com/s/app/pr-comms/sell-with-us/01-testimonial-02.jpg', 30],
    ['home', 'testimonial_3', 'quote', 'richtext', '“Partnering with Nawy helped Baybee grow fast and reach more customers across the UAE and KSA. Their support, tools, and reach made launching smooth and scaling easy. We’re excited to keep building on this success together.”', 'الشراكة مع ناوي ساعدت Baybee على النمو بسرعة والوصول إلى عدد أكبر من العملاء في الإمارات والسعودية. دعمهم، وأدواتهم، وانتشارهم الواسع جعلوا الإطلاق سلس والتوسع سهل. نحن متحمسون لمواصلة هذا النجاح معا.', null, 31],
    ['home', 'testimonial_3', 'name', 'text', 'Zouban Shalin, Brand Director', 'زوبان شالين، مدير العلامة التجارية', null, 32],
    ['home', 'testimonial_3', 'company', 'text', 'Baybee Brand', 'Baybee Brand', null, 33],
    ['home', 'testimonial_4', 'photo', 'image', 'Sreeja V.S, Head of e-Commerce', 'سريجا في. إس، رئيسة قسم التجارة الإلكترونية', 'https://f.nooncdn.com/s/app/pr-comms/sell-with-us/01-testimonial-01.jpg', 40],
    ['home', 'testimonial_4', 'quote', 'richtext', '“Big thanks to the Nawy team for jumping in when our original account got unexpectedly blocked. They acted fast, got us back online, and had our back throughout. In just three months, our sales shot up by over 500% — that kind of growth only happens when you’ve got a team that truly shows up.”', 'نتوجه بجزيل الشكر لفريق ناوي على دعمهم الفوري عندما تم حظر حسابنا بشكل مفاجئ. تدخلوا بسرعة، أعادونا للعمل خلال وقت قياسي، وكانوا إلى جانبنا في كل خطوة. خلال ثلاثة أشهر فقط، ارتفعت مبيعاتنا بأكثر من 500٪ — هذا النوع من النمو لا يتحقق إلا بوجود فريق حقيقي يلتزم ويقف مع شركائه بكل احترافية.', null, 41],
