    ['sellers', 'solution_brand_ads', 'title', 'text', 'Brand Ads', 'إعلانات العلامة التجارية', null, 40],
    ['sellers', 'solution_brand_ads', 'description', 'text', 'Promote your products and brand in a visually appealing and prominent way within Nawy\'s browse, search, and relevant product detail pages. Display multiple products within one ad, showcasing a wider range of offerings and potentially attracting a broader audience.', 'قم بالترويج لمنتجاتك وعلامتك التجارية بطريقة بصرية جذابة وبارزة داخل صفحات ناوي للتصفح، البحث، وصفحات تفاصيل المنتج ذات الصلة. بإمكانك أيضا عرض منتجات متعددة داخل إعلان واحد، وإبراز مجموعة واسعة من منتجاتك وجذب جمهور أكبر.', null, 41],
    ['sellers', 'solution_brand_ads', 'link_label', 'text', 'Learn More', 'اعرف أكثر', null, 42],
