    ['sellers', 'testimonials', 'eyebrow', 'text', 'Hear from our satisfied customers', 'استمع إلى آراء عملائنا', null, 50],
    ['sellers', 'testimonials', 'prev_aria', 'text', 'Previous', 'السابق', null, 51],
